CREATE TABLE `appointment_cancellation_request` (
  `id` bigint NOT NULL,
  `appointment_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预约类型: grooming, hospital, door_cleaning',
  `appointment_id` bigint NOT NULL COMMENT '预约ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `reason` varchar(1024) COLLATE utf8mb4_general_ci NOT NULL COMMENT '取消原因',
  `status` varchar(24) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT 'pending-待确认, approved-已同意, rejected-已拒绝',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='取消预约申请';

