--
-- 表的结构 `appointment_change_request`
--

CREATE TABLE `appointment_change_request` (
  `id` bigint NOT NULL,
  `appointment_type` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '预约类型: unified, grooming, hospital, door_cleaning',
  `appointment_id` bigint NOT NULL COMMENT '预约ID',
  `requested_date` date DEFAULT NULL COMMENT '申请变更的日期',
  `requested_time_slot` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请变更的时间段',
  `requested_location` varchar(512) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请变更的地址/地点',
  `requested_remark` varchar(1024) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请变更的备注',
  `requested_contact_phone` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '申请变更的联系电话',
  `status` varchar(24) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending' COMMENT 'pending-待确认, approved-已同意, rejected-已拒绝',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `requested_key_handover_method` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上门铲屎：申请变更的钥匙给予方式',
  `requested_key_return_method` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '上门铲屎：申请变更的钥匙归还方式',
  `requested_pet_id` bigint DEFAULT NULL COMMENT '申请变更的宠物ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='预约变更申请';

