--
-- 表的结构 `daily_topic`
--

CREATE TABLE `daily_topic` (
  `id` bigint NOT NULL COMMENT '专题ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '专题标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '专题描述',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '正文富内容 JSON：[{t:"text",v:"段落"},{t:"img",v:"url"}]',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '封面图片URL',
  `theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '主题分类（如：宠物健康、营养、训练等）',
  `publish_date` date NOT NULL COMMENT '发布日期',
  `status` tinyint DEFAULT '1' COMMENT '状态：0-草稿，1-已发布，2-已下线',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `view_count` int DEFAULT '0' COMMENT '浏览量',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每日专题帖子表' ROW_FORMAT=DYNAMIC;

