INSERT INTO `daily_topic` (`id`, `title`, `description`, `content`, `cover_image`, `theme`, `publish_date`, `status`, `sort_order`, `view_count`, `like_count`, `create_time`, `update_time`) VALUES
(21, '新手养猫系列|猫咪饮食避坑指南，喂对粮才是养出健康毛孩子的关键', NULL, '[{\"t\":\"text\",\"v\":\"新手铲屎官最头疼的问题里，\\\"给猫咪喂什么\\\"绝对排第一。面对市面上五花八门的猫粮、猫罐头、零食，看着各种\\\"无谷”鲜肉”\\\"高蛋白\\\"的宣传，再加上身边人各有各的说法，很容易陷入迷茫:到底该选哪种粮?多久喂一次?哪些能喂哪些不能喂?其实猫咪饮食的核心很简单:适配年龄、营养均衡、避开雷区。很多新手因为喂错粮，导致猫咪出现软便、呕吐、掉毛严重，甚至患上肠胃病、肾病，追悔\\n莫及。\\n今天这篇饮食指南，专门为新手量身打造，从猫粮选择、喂食方式，到零食搭配、饮食禁忌，一次性讲清楚，帮你避开90%的饮食坑，喂出健康又可爱的毛孩。子~\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413010518-19b0e959.jpg\"},{\"t\":\"text\",\"v\":\"一、新手选粮:记住3个核心，不被商家套路选猫粮是养猫饮食的第一步，也是最关键的一步。新手不用盲目追求\\\"进口”\\\"贵价\\\"，只要抓住3个核心，就能选到适合自家猫咪的好粮，避开商家的宣传套路\\n1.先看年龄:幼猫、成猫、老年猫，粮不能混喂猫咪在不同年龄段，对营养的需求完全不同，混喂粮会导致营养过剩或不足，影响身体健康。新手一定要根据猫咪的年龄选粮，这是最基础的原则。幼猫(≤12个月):处于快速生长发育期，需要高蛋白、高钙、易消化的幼猫粮，帮助骨骼和身体发育，建议选择颗粒较小、易咀嚼的款式，方便幼猫进食;成猫(1-7岁):身体发育成熟，营养需求稳定，选择成猫粮即可，重点关注营养均衡，避免过高的脂肪，防止猫咪肥胖;老年猫(≥7岁):新陈代谢变慢，肠胃功能减弱，需要选择老年猫粮，低脂肪、易消化、富含膳食纤维，同时补充关节营养，减轻身体负担。2.再看配料表:3个重点，避开\\\"垃圾粮”配料表是猫粮的\\\"身份证\\\"，新手看不懂复杂的成分只要抓住3个重点，就能快速判断猫粮好坏，避开\\\"三无垃圾粮”。\\n重点一:第一位必须是\\\"鲜肉\\\"或\\\"肉粉\\\"，且明确标注肉类来源(如鸡肉、牛肉、鱼肉)，避免出现\\\"肉类副产品”\\\"动物内脏\\\"等模糊表述一一猫咪是肉食动物，蛋白质是核心营养，优质肉类才能满足需求;重点二:避开\\\"谷物”\\\"麸质\\\"等成分，尤其是小麦、玉米、大豆，很多猫咪对谷物过敏，会导致软便、皮肤瘙痒、掉毛严重，优先选择无谷猫粮;重点三:拒绝添加\\\"诱食剂”\\\"防腐剂”\\\"色素\\\"，这类成分对猫咪肠胃和肝脏伤害很大，配料表中出现\\\"风味剂”\\\"人工色素”\\\"BHA/BHT\\\"等，直接pass。3.最后看营养值:满足基础需求即可，不用追求\\\"极致”\\n新手不用过分纠结营养值的具体数字，只要满足猫咪的基础需求，就是合格的猫粮。一般来说，幼猫粮粗蛋白≥30%、粗脂肪≥18%;成猫粮粗蛋白≥28%、粗脂肪≥15%，就能满足猫咪的日常营养需求。小贴士:第一次买猫粮，建议先买小包装试吃，观察猫咪的进食情况和粪便状态，如果猫咪爱吃、粪便成型，再批量购买;如果出现软便、呕吐，说明这款粮不适合，及时更换。\\n二、喂食方式:这4个细节，决定猫咪肠胃健康选对了猫粮，还要喂对方式，否则再好的粮，也会伤害猫咪的肠胃。很多新手因为喂食不当，导致猫咪出现肠胃问题，这些细节一定要注意。\\n1.喂食频率:幼猫少量多餐，成猫定时定量幼猫肠胃功能弱，一次吃不了太多，且生长发育需要持续补充营养，建议少量多餐:3-4个月龄，每天喂4-5次;5-12个月龄，每天喂3-4次，每次喂食量以猫咪5-10分钟吃完为准，不要过量。成猫肠胃功能成熟，建议定时定量喂食，每天喂2次(早晚各一次)，每次喂食量根据猫咪的体重和活动量调整，避免暴饮暴食一一长期过量喂食，会导致猫咪肥胖，引发糖尿病、心脏病等问题。2.换粮:循序渐进，避免肠胃应激很多新手会因为猫咪不爱吃当前的粮，或者想给猫咪换更好的粮，直接一次性更换，这样很容易导致猫咪肠胃不适，出现软便、腹泻、呕吐等情况。正确的换粮方法:循序渐进，分5-7天完成。第1-2天，I旧粮80%+新粮20%;第3-4天，旧粮50%+新粮50%;第5-6天，I旧粮20%+新粮80%;第7天，完全换成新粮。换粮期间，多观察猫咪的粪便和食欲，有异常及时停止换粮。\\n3.饮水:必须保证\\\"新鲜、充足\\\"，别忽视!很多新手只关注猫粮，却忽视了猫咪的饮水，这是非常危险的一一猫咪天生不爱喝水，长期缺水会导致泌尿系统疾病(如尿结石、肾衰竭)，这是猫咪的高发疾病，严重时会危及生命。建议每天更换一次饮用水，保证水盆里有干净的温水;可以准备多个水盆，放在家里不同的位置，方便猫咪随时喝水;如果猫咪实在不爱喝水，可以尝试用饮水机(流动的水更能吸引猫咪)，或者在猫粮里少量加水(不要太多，避免猫粮变质)\\n4.喂食环境:安静、固定，不打扰猫咪进食时很敏感，喜欢安静、固定的环境，避免被打扰。建议将食盆和水盆放在安静、远离猫砂盆的地方(猫咪不喜欢在厕所附近吃饭)，不要频繁更换喂食位置;喂食时，不要追着猫咪喂，也不要在猫咪进食时大声说话、打闹，让猫咪安心进食。三、零食选择:解馋可以，但别当主食!很多新手喜欢用零食讨好猫咪，看着猫咪吃得开心就频繁喂食，却不知道，频繁喂零食不仅会让猫咪挑食、不爱吃主食，还会导致营养不均衡、肥胖，甚至伤害肠胃。1.零食选择:优先选\\\"天然、无添加\\\"的款式选择猫咪零食时，同样要看好配料表，优先选择天然、无添加的款式，比如冻干、烘干肉干、猫条(无诱食剂、无防腐剂)，避免选择\\\"火腿肠”\\\"人类零食”\\\"廉价猫条\\\"，这类零食添加剂多，对猫咪健康有害。2.喂食频率:每周2-3次，每次少量零食只能作为\\\"奖励\\\"，不能当主食，建议每周喂食2-3次，每次少量(比如1-2根猫条、1-2块冻干)，可以在猫咪听话、互动后喂食，既能增进感情，也不会让猫咪挑食。3.避坑提醒:这些\\\"零食\\\"绝对不能喂除了人类的禁忌食物(之前手册中提到的巧克力、洋葱等)，还有一些看似适合猫咪的零食，其实也不能喂:比如牛奶(猫咪大多乳糖不耐受)、生肉(可能含有寄生虫)、咸肉(高盐伤肾)、水果(除了少量苹果、蓝莓，大多水果含糖量高，会导致肥胖)。\\n四、新手常见饮食误区，看完直接避坑总结了几个新手最容易踩的饮食误区，看完这几点再也不用为猫咪喂食发愁，也能避免伤害猫咪的健康。\\n误区1:贵的粮就是好粮，越贵越好其实猫粮的好坏，和价格没有绝对的关系，关键看配料表和营养值。有些进口粮价格昂贵，但配料表一般;有些国产粮价格适中，却用料扎实、营养均衡。新手选粮，优先看配料和营养，再结合自己的预算，不用盲目追求贵价。误区2:猫咪爱吃，就一直喂同一款粮猫咪长期吃同一款粮，会导致营养单一，也可能出现挑食的情况。建议每6-12个月，给猫咪更换一次猫粮(换粮时仍需循序渐进)，既能补充不同的营养，也能避免猫咪挑食。误区3:给猫咪喂人类的饭菜，省事儿又有营养人类的饭菜大多高盐、高油、高糖，还含有葱姜蒜等对猫咪有害的成分，长期喂食会导致猫咪肾脏负担加重、肠胃不适，甚至引发疾病。猫咪有自己的饮食习性，一定要喂专用的猫粮和零食，不要喂人类饭菜。误区4:猫咪胖一点更可爱，多喂点没关系猫咪肥胖并不是可爱，而是一种疾病，会引发糖尿病、心脏病、关节疾病等多种问题，缩短猫咪的寿命。新手一定要控制猫咪的喂食量，定期陪猫咪运动，保持健康的体重。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413010855-99a88ce9.jpg\"},{\"t\":\"text\",\"v\":\"最后:饮食健康，是猫咪长寿的基础猫咪的肠胃很脆弱，饮食的好坏，直接决定了猫咪的健康和寿命。作为新手铲屎官，不用追求多么专业的喂养方式，只要记住\\\"适配年龄、营养均衡、定时定量、避开雷区\\\"这几个核心，就能喂好猫咪。每一只毛孩子，都需要我们细心呵护，而喂对粮、喂好粮，就是我们爱它的第一步。愿每一位新手铲屎官，都能掌握正确的喂食方法，养出健康、活泼、长寿的毛孩子\"}]', 'https://situationship.icu/upload/files/files-20260413010923-9ecd602a.jpg', 'recommend', '2026-04-12', 1, 1, 4, 0, '2026-04-13 01:09:32', '2026-04-13 01:09:38'),
(22, '养猫科普|如何鉴定猫咪的性别?', NULL, '[{\"t\":\"text\",\"v\":\"要区分公猫和母猫并不总是那么容易，而要辨别幼猫或已经绝育的猫咪性别就更难了。然而，有一些迹象和行为可以让主人，去更容易判断一只猫的性别。\\n\\n1.给幼猫鉴定性别\\n\\n对于那些领养小猫的人来说，这只小猫可能只有几个星期大。新生儿和幼猫发育不成熟，以至于几乎不可能分辨它们的性别。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413011225-ecf547b8.jpg\"},{\"t\":\"text\",\"v\":\"\\n然而，一旦它们六到八周大，它们的生殖器在视觉上就会变得更加明显。然而，阴茎在公猫身上通常是看不到的，而且主人也不太可能感觉到或看到阴囊。因此，明显没有阴茎或睾丸并不意味着小猫是雌性。\\n\\n作为经验，繁殖者使用标点符号来识别幼猫或已经绝育的猫的性别。要做到这一点，轻轻提高宠物的尾巴;开始轻轻地爱抚，并试着抚摸猫的下背部，因为这样他或她可能会提高尾巴自己开始咕噜咕噜。\\n2.小母猫的性别鉴定\\n\\n当观察母猫的生殖器区域，也就是尾巴下方的空间时，它看起来就像倒立的感叹号在肛门下面的阴道区域有一条长长的裂缝。肛门和阴道通常只有大约一厘米的距离。在小猫身上，肛门和阴道看起来都像圆点，甚至可能更靠近。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413011419-a80f9f00.jpg\"},{\"t\":\"text\",\"v\":\"\\n公猫的肛门和阴茎之间的距离较大，睾丸位于中间，比较幼年的猫可能看不到明显的睾丸或者说阴囊。这两个开口看起来更像点、圆圈或冒号，而不像狭缝或线条。\\n\\n对于成年猫来说，可以使用和幼猫相同的性别鉴定技术;这通常也适用于已经绝育的和未绝育的猫。如果宠物没有绝育，那么根据外表和行为来辨别它们的性别就会容易得多。一旦猫被绝育，性别之间就没有明显的行为差异，明显的差异很可能与个别猫的性情有关。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413011528-c12040f6.jpg\"},{\"t\":\"text\",\"v\":\"3.未绝育成年猫的性别鉴定\\n未绝育的公猫有明显的睾丸(隐睾除外)和宽阔的下颚。他们也有独特的行为，开始于他们发情的时候。未绝育的公猫往往更加活跃和好斗。他们也更有可能通过尿液喷洒来标记他们的领地。\\n\\n没有绝育的母猫会有周期性的发情行为。在当她试图寻找配偶时，她的行为会发生巨大的变化，发情的母猫通更会博取注意，声音也更大。\\n\\n4.已绝育成年猫的性别鉴定\\n\\n绝育过的母猫仍然会表现出打滚，蹭地板的样子。但如果养猫咪时已经成年且未知是否绝育，需要去医院，兽医会用一些专门的检测方法来判断是否绝育。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413011702-9ddb70c6.jpg\"},{\"t\":\"text\",\"v\":\"\\n绝大多数绝育后的公猫仍然会出现阴囊的残余，肛门和阴茎仍然相对靠近。绝育的猫不会表现出典型的雄性或雌性行为。绝育的公猫通常比未绝育公猫更安静，而绝育的母猫不会发情。\\n虽然所有的猫看起来都非常相似，但某些颜色和身体特征对于特定的性别来说是独一无的。\\n具体来说，玳瑁或着三花的公猫是极其罕见的。对于那些养着三花猫的人来说，很有可能宠物是母猫的。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413011753-929f5519.jpg\"},{\"t\":\"text\",\"v\":\"\\n对于那些养了一只橘猫母猫很少有橘色的。\\n的人来说，很有可能是一只公猫。\\n生过小猫的母猫更有可能有明显的乳头(尽管雄猫和雌猫都有乳头)。母猫在发情期时可能会有阴道分泌物，而怀孕的猫会有低垂的、膨胀的腹部。\"}]', 'https://situationship.icu/upload/files/files-20260413011815-52e6214c.jpg', 'basic', '2026-04-13', 1, 0, 2, 0, '2026-04-13 01:19:44', '2026-04-13 01:57:20'),
(34, '养猫科普|猫到底该喝多少水?', NULL, '[{\"t\":\"text\",\"v\":\"为了达到最佳健康状态，猫咪每天都需要新鲜的饮用水。水可以帮助肾脏带走血液中的毒素，是至关重要的。水也有助于保持其他器官组织的水分和健康。猫咪脱水是很危险的，如果不治疗，可能会导致死亡。\\n处于肾衰竭的猫，无论是急性肾衰竭还是慢性肾衰竭，往往需要通过静脉注射或皮下滴注的方式提供额外的液体。后者的治疗通常是在家里进行的，而且相对容易学习和执行。对大多数猫来说，这些治疗后的改善是明显的、可见的。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413021744-24ac1fb4.jpg\"},{\"t\":\"text\",\"v\":\"01\\n过度饮水\\n过度饮水可能是猫咪甲状腺功能亢进症或猫咪糖尿病的危险信号。虽然猫咪在炎热的天气里可能会本能地多喝水，但与所有猫咪的习惯一样，了解猫咪的正常饮水量是很重要的。如果与之前相比，它们突然开始大量饮水并出现其他症状，应立即向兽医咨询。\\n02\\n水的需求取决于饮食\\n正常猫咪会自发调整饮水量保持水分平衡。猫的身体组织由大约67%的水组成。巧合的是，这与它们在野外捕捉和食用的猎物中的水的比例差不多。相比之下，干猫粮含有约10%的水分，而猫罐头的水分含量至少为75%，这使其成为良好的水源。同样地，吃干粮的猫也需要更多的饮用水。\\n03\\n建议\\n1\\n无论猫咪的饮食习惯如何，请为你的猫咪随时提供新鲜、干净的水，最好使用自动饮水机。\\n2\\n注意脱水的迹象。可以通过拉起猫咪颈背上松弛的皮肤来测试猫咪是否脱水。如果它马上回弹，说明猫咪有足够的水分。如果它迟迟不退，则可以怀疑出现了脱水现象。试着在猫咪的罐头中加入水，或在它们的饮用水中加入一两块冰块，使其更有趣。如果颈部皮肤没有明显消退，而猫咪又出现了其他生病的迹象，请立即咨询宠物医生。\\n3\\n了解您的猫的饮水习惯。如果它们突然\\\"断水\\\"或开始过量饮水，请咨询宠物医生。\"}]', 'https://situationship.icu/upload/files/files-20260413021826-7daed45c.jpg', 'feeding', '2026-04-13', 1, 0, 3, 0, '2026-04-13 02:14:38', '2026-04-13 02:18:34'),
(35, '养猫科普|猫咪日常护理实操大全', NULL, '[{\"t\":\"text\",\"v\":\"开门见山，这次讲4个日常的护理，希望能够帮到大家~\\n\\n1.日常毛皮护理：梳毛几乎是每个养猫人都会做的事情了。梳毛除了可以帮助猫咪减少舔入体内的猫毛、减少毛球症，还能帮助大家在梳毛的过程中发现可能的皮肤病。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413022058-af715bc3.jpg\"},{\"t\":\"text\",\"v\":\"猫咪的梳毛频次其实是根据猫咪毛发的长短来决定的。长毛猫一般建议每日至少全身梳毛一次;中长毛发的猫一般建议2-3次/周;短毛猫一般建议一周一次即可;无毛猫建议每周清洁2-3次。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413022139-b19a78a4.jpg\"},{\"t\":\"text\",\"v\":\"随着养猫人变多，梳毛的工具也越多越多了.....简直让人陷入选择困难症......建议大家在使用梳子的时候，注意下面这几点:\\n使用梳子注意事项\\n1.选择针梳的时候要特别注意下手的力道，不要刮伤猫咪皮肤;\\n2.使用任何梳子梳猫咪头部时，要注意不要伤到猫咪的眼睛;\\n3.多猫家庭建议:一猫一梳，避免皮肤病传染，也便于找到猫咪喜欢的梳子类型。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413022238-75dfb4b4.jpg\"},{\"t\":\"text\",\"v\":\"梳毛步骤\\n1.梳毛前:让猫咪放松，不要抗拒你的梳毛的动作;\\n2.梳毛中:猫咪整个身体的刷毛是需要分为几个板块完成的。从猫咪的脸颊开始，往脖颈或下巴处梳毛;从猫咪的头部开始，往背部和身体处刷毛;从胳肢窝开始，往腹部梳毛;\\n3.梳毛后:可以用玩耍和零食作为奖励。\"}]', 'https://situationship.icu/upload/files/files-20260413022348-efe58317.jpg', 'care', '2026-04-12', 1, 0, 3, 0, '2026-04-13 02:23:52', '2026-04-13 02:23:52'),
(36, '猫猫疫苗全解', NULL, '[{\"t\":\"text\",\"v\":\"今天要给大家掰扯一个争议非常大的问题:疫苗。\\n疫苗肯定是要打的，但是市面上对于:打什么、怎么打、打几次......这些问题的讨论层出不穷，此起彼伏。\\n本着科学养猫的观念和大家探讨一下这个\\\"危险边缘\\\"的话题.\\n猫的初始疫苗与后续疫苗\\n初始疫苗的来源其实简单粗暴:母乳。(母源对于幼猫来说，这是被动免疫，来自抗体)外界。这是猫咪喵喵坠地之后的第一道免疫防线，因此，没有吃到母乳的幼猫体质一般会更弱，也更容易生病。\\n随着时间的流逝，母乳的抗体会逐渐减弱。这个时候，猫咪自身的免疫系统就开启了长达一生的工作一一主动免疫。小到我们没有发现的病毒，大到需要打疫苗抗衡的病毒，都是猫咪主动免疫的过程。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413022604-dd56be46.jpg\"},{\"t\":\"text\",\"v\":\"随着时间的流逝，这些主动免疫产生的抗体会逐渐变弱，这时候就需要\\\"补打疫苗”，从而让猫咪的身体再一次主动免疫，产生抗体，保护自己。\"}]', 'https://situationship.icu/upload/files/files-20260413022620-cfccd2e7.jpg', 'medical', '2026-04-12', 1, 0, 0, 0, '2026-04-13 02:26:23', '2026-04-13 02:26:27'),
(37, '驱虫药真的需要1月1次吗?驱虫药完全攻略', NULL, '[{\"t\":\"text\",\"v\":\"夏天到了，蚊虫滋生，掀起了一股驱虫热。打开各大APP，发现满眼都是各大药厂的驱虫药广告，各种营销术语搞得人眼冒金星:什么内外同驱啦、广谱驱虫啦、安全无毒啦、药效持久啦.....\\n相信大家或多或少都会有些疑问:到底什么是内驱外驱?各种不同品牌的驱虫药到底有什么不同?驱虫药到底多久用一次?驱虫药为什么这么贵?可以自己在家里给猫驱虫吗?\\n这篇文章就给大家对驱虫这件事情进行一个全面、详细的分析和建议。\\n首先，我们来看一下到底什么是内驱外驱?\\n内驱和外驱字面上理解是体内用的驱虫药和体外用的驱虫药。其实这个理解是不够准确的。\\n更准确的理解是:内驱指对体内寄生虫有用的驱虫药、外驱指对体外寄生虫有用的驱虫药。\\n有些外用的驱虫药也能杀灭体内的寄生虫;有些内服的驱虫药也能杀灭体外的寄生虫。\\n(感觉把自己都绕进去了......)\\nAnyway，记住一点就可以了:不要管什么内驱、外驱、内外同驱的概念了，最重要的是看驱虫药到底能驱什么虫!\\n各个品牌的驱虫药都有些什么不同?\\n注:我这里只列举了一些猫咪常用的大品牌驱虫药。一些小品牌的药不是说完全不好，只是自己没有用过，没有自己实证，就不推荐给大家了。\\n各个品牌的驱虫药在价格、用法、适用年龄、驱虫的种类等方面上各有不同。具体可以参考下表:\"}]', 'https://situationship.icu/upload/files/files-20260413022853-17368c0b.jpg', 'health', '2026-04-12', 1, 0, 2, 0, '2026-04-13 02:29:04', '2026-04-13 02:29:04'),
(38, '如何读懂猫咪的情绪?', NULL, '[{\"t\":\"text\",\"v\":\"猫有情绪吗?猫咪当然有情绪!从兴奋、高兴到紧张和沮丧，猫可以表现出一系列的情绪。\\n或许会有一天，会有一种设备可以轻松地翻译猫咪的行为，这样我们也就可以准确地知道猫咪的感受。在我们掌握这项技术之前，铲屎官们需要学习如何理解你的猫咪的肢体语言和叫声，以便了解它的情绪。\"},{\"t\":\"img\",\"v\":\"https://situationship.icu/upload/files/files-20260413023000-ca131f38.jpg\"},{\"t\":\"text\",\"v\":\"猫用整个身体进行交流，从尾巴到耳朵和眼睛。虽然猫咪的肢体语言可能很复杂，但是通过以下这些小指导，可以帮助你解读你的猫咪在想什么以及读懂它们的感受。\\n然而，请记住，每只猫，都是特殊的个体，所以猫咪表现某些情绪的确切方式可能是独一无二的。\\n下面我们来看看猫咪放松、快乐、好奇、恐惧、愤怒以及生病时的一些肢体语言。\\n\\n猫咪表达情绪的肢体语言\\n猫咪感到放松或满足大多数时候，猫咪都感到放松和满足。以下是要注意的地方:\\n身体:\\n一只放松的猫，通常侧卧或仰卧，后腿张开。\\n尾巴:\\n它们的尾巴基本上是静止的，不会摇晃。\\n眼睛:\\n它们可能闭着眼，也可能是半睁开着的。当一只猫用半睁开的眼睛看着你时，或者它们在\\\"慢慢的眨眼\\\"，这是一种对铲屎官的\\\"欣赏”，因为这表明它们足够信任你，不会在你周围很警惕。\\n耳朵:\\n一只放松的猫的耳朵会竖起并且指向前方在一个中立的位置。\\n行为:\\n它们会呼噜呼噜地叫，或者揉捏爪子(也被称\\\"踩奶\\\")一只开心满足的猫通常会以一种放松的方式打扮自己和主人相处。\"}]', 'https://situationship.icu/upload/files/files-20260413022949-63bdf1f9.jpg', 'behavior', '2026-04-12', 1, 0, 5, 1, '2026-04-13 02:30:58', '2026-04-13 02:30:58');

