--
-- 表的结构 `grooming_appointments`
--

CREATE TABLE `grooming_appointments` (
  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL COMMENT 'User ID',
  `pet_id` bigint NOT NULL COMMENT 'Pet ID',
  `service_id` bigint DEFAULT NULL COMMENT 'Grooming service ID',
  `service_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'grooming' COMMENT 'Service type',
  `store_id` bigint DEFAULT NULL COMMENT '预约门店ID',
  `date` date NOT NULL COMMENT 'Appointment date',
  `time_slot` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Appointment time slot',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'Service address',
