(22, '基础体检套餐', '年度常规健康评估，含问诊、基础生理指标检查与健康档案建立。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '199.00', 'https://situationship.icu/upload/files/files-20260324002605-3a155877.jpg', '常规体检', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:05', '[\"专业兽医问诊评估\", \"体重与体况评估\", \"血常规与生化项目按需加项\"]', '[\"体检前需禁食 8 小时，禁水 2 小时\", \"如有慢性病史请提前告知\", \"携带疫苗本以便登记\"]', 45, '#e9f5ff', '[\"体检\", \"健康档案\"]', 1, 1, '2025-11-09 23:36:04', '2026-03-24 00:26:06', 0),
(23, '疫苗接种&驱虫组合', '根据宠物年龄与生活习惯定制免疫计划，并提供体重评估和驱虫建议。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '149.00', 'https://situationship.icu/upload/files/files-20260324002612-995f7957.jpg', '疫苗与驱虫', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:12', '[\"专属免疫方案定制\", \"体重体况评估\", \"口服/外用驱虫计划\"]', '[\"接种前确认健康状态良好\", \"若近期用药请提前说明\", \"幼宠需监护人陪同\"]', 30, '#fff3e0', '[\"疫苗\", \"驱虫\", \"预防保健\"]', 1, 2, '2025-11-09 23:36:04', '2026-03-24 00:26:12', 0),
(24, '术前综合评估', '手术前的全面风险评估，含血液、影像与麻醉方案建议，保障术中安全。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '399.00', 'https://situationship.icu/upload/files/files-20260324002646-cd60e33d.jpg', '手术评估', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:46', '[\"血常规与生化检查\", \"心电图与 X 光影像\", \"麻醉风险等级评估\"]', '[\"手术前 12 小时禁食禁水\", \"如有既往病史携带病例与化验单\", \"按约定时间到院办理住院手续\"]', 90, '#f3e8ff', '[\"手术\", \"麻醉\", \"术前评估\"]', 1, 3, '2025-11-09 23:36:04', '2026-03-24 00:26:47', 0),
(25, '慢病管理复诊', '针对糖尿病、肾病等慢性疾病提供随访与用药调整，含咨询与饮食建议。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '259.00', 'https://situationship.icu/upload/files/files-20260324002627-cb12a958.jpg', '慢病管理', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:27', '[\"血糖/肾指标追踪\", \"用药疗程评估\", \"营养与运动建议\"]', '[\"复诊前记录一周用药与饮食\", \"携带自用药品标签便于核对\", \"如有异常症状请提前电话沟通\"]', 40, '#eafbf2', '[\"慢病管理\", \"复诊\"]', 0, 4, '2025-11-09 23:36:04', '2026-03-24 00:26:28', 0),
(26, '口腔洁治抛光', '高压雾化洁牙与抛光，改善口臭并降低口腔炎症风险，术后含银离子护理。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '489.00', 'https://situationship.icu/upload/files/files-20260324002634-ea6a2be9.jpg', '口腔保健', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:34', '[\"超声波洁治\", \"专业抛光与抑菌冲洗\", \"术后口腔护理指导\"]', '[\"麻醉前 8 小时禁食禁水\", \"手术前需完成血液筛查\", \"术后 2 小时内禁食\"]', 70, '#fdebea', '[\"口腔\", \"洁牙\"]', 1, 5, '2025-11-09 23:36:04', '2026-03-24 00:26:35', 0),
(27, '术后康复理疗', '针对术后或外伤恢复期宠物提供低频理疗、关节拉伸与伤口护理，促进康复。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '329.00', 'https://situationship.icu/upload/files/files-20260324002641-65f4791f.jpg', '康复理疗', 'active', '2025-11-09 15:36:04', '2026-03-23 16:26:41', '[\"低频电刺激理疗\", \"关节与肌群拉伸\", \"伤口护理与换药\"]', '[\"理疗前 2 小时进食可少量\", \"请提前提供手术/外伤记录\", \"配合安排家属在场辅助\"]', 50, '#f0f5e9', '[\"康复\", \"理疗\"]', 0, 6, '2025-11-09 23:36:04', '2026-03-24 00:26:42', 0);

