--
-- 表的结构 `litter_services`
--

CREATE TABLE `litter_services` (
  `id` bigint NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `introduction` json DEFAULT NULL COMMENT '商品介绍列表',
  `instructions` json DEFAULT NULL COMMENT '使用须知列表',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `price` decimal(10,2) NOT NULL,
  `duration` int DEFAULT NULL,
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `bg_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'active',
  `is_recommended` tinyint(1) DEFAULT '0',
  `sort_order` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT '0'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='上门铲屎服务' ROW_FORMAT=DYNAMIC;

--
-- 转存表中的数据 `litter_services`
--

INSERT INTO `litter_services` (`id`, `name`, `description`, `introduction`, `instructions`, `category`, `price`, `duration`, `image_url`, `bg_color`, `tags`, `status`, `is_recommended`, `sort_order`, `created_at`, `updated_at`, `is_deleted`) VALUES
(30, '基础上门铲屎服务', '专业上门铲屎服务，包括清理猫砂盆、更换猫砂、清洁周围环境。适合日常维护，让您的爱宠拥有干净舒适的生活环境。', '[\"专业上门铲屎服务，包括清理猫砂盆、更换猫砂、清洁周围环境。适合日常维护，让您的爱宠拥有干净舒适的生活环境。\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'basic', '39.00', 30, 'https://situationship.icu/upload/files/files-20260324004421-3c156cdd.jpg', '#e3f2fd', '[]', 'active', 1, 1, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(31, '深度清洁铲屎服务', '深度清洁铲屎服务，包括彻底清理猫砂盆、消毒杀菌、更换全新猫砂、清洁周围区域。适合长时间未清理或需要彻底清洁的情况。', '[\"适用宠物: 猫咪、狗狗\", \"适用宠物性别: 公母均可\", \"服务范围: 室内宠物生活区域深度清洁\", \"服务时长: 60分钟\", \"包含内容: 彻底清理猫砂盆、消毒杀菌、更换全新猫砂、清洁周围区域\", \"服务时间: 每日9:00-18:00\", \"需要提前2小时预约\", \"适合长时间未清理的情况\", \"服务完成后提供清洁报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'deep-cleaning', '69.00', 60, 'https://situationship.icu/upload/files/files-20260324004435-982e6e04.jpg', '#f3e5f5', '[\"上门服务\", \"深度清洁\", \"消毒杀菌\"]', 'active', 1, 2, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(32, '定期维护铲屎服务', '每周定期上门铲屎服务，包括日常清理、猫砂更换、环境检查。适合工作繁忙的宠物主人，确保爱宠始终拥有干净的生活环境。', '[\"适用宠物: 猫咪、狗狗\", \"适用宠物性别: 公母均可\", \"服务范围: 室内宠物生活区域定期维护\", \"服务时长: 30分钟/次\", \"包含内容: 日常清理、猫砂更换、环境检查\", \"服务频率: 每周定期上门\", \"服务时间: 每日9:00-18:00\", \"适合工作繁忙的宠物主人\", \"服务完成后提供清洁报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'regular', '199.00', 30, 'https://situationship.icu/upload/files/files-20260324004442-c65e7653.jpg', '#e8f5e9', '[\"上门服务\", \"定期维护\", \"包月服务\"]', 'active', 1, 3, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(33, '快速铲屎服务', '30分钟快速铲屎服务，适合紧急情况或临时需要。快速清理猫砂盆，更换猫砂，让您的爱宠立即拥有干净的环境。', '[\"适用宠物: 猫咪、狗狗\", \"适用宠物性别: 公母均可\", \"服务范围: 室内宠物生活区域快速清洁\", \"服务时长: 30分钟\", \"包含内容: 快速清理猫砂盆、更换猫砂\", \"服务时间: 每日9:00-18:00\", \"适合紧急情况或临时需要\", \"快速响应，立即服务\", \"服务完成后提供清洁报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'basic', '29.00', 30, 'https://situationship.icu/upload/files/files-20260324004449-019187b6.jpg', '#fff3e0', '[\"上门服务\", \"快速服务\"]', 'active', 0, 4, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(34, '豪华铲屎套餐', '豪华铲屎套餐服务，包括深度清洁、消毒杀菌、更换高级猫砂、环境美化、宠物健康检查。全方位呵护您的爱宠。', '[\"适用宠物: 猫咪、狗狗\", \"适用宠物性别: 公母均可\", \"服务范围: 室内宠物生活区域豪华清洁\", \"服务时长: 90分钟\", \"包含内容: 深度清洁、消毒杀菌、更换高级猫砂、环境美化、宠物健康检查\", \"服务时间: 每日9:00-18:00\", \"全方位呵护您的爱宠\", \"使用高级猫砂和清洁用品\", \"服务完成后提供详细清洁报告和健康检查报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'deep-cleaning', '99.00', 90, 'https://situationship.icu/upload/files/files-20260324004457-7640c8be.jpg', '#fce4ec', '[\"上门服务\", \"豪华套餐\", \"健康检查\"]', 'active', 1, 5, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(35, '多猫家庭铲屎服务', '专为多猫家庭设计的铲屎服务，包括多个猫砂盆的清理、大量猫砂更换、环境全面清洁。适合养有多只猫咪的家庭。', '[\"适用宠物: 多只猫咪\", \"适用宠物性别: 公母均可\", \"服务范围: 室内多猫生活区域全面清洁\", \"服务时长: 60分钟\", \"包含内容: 多个猫砂盆的清理、大量猫砂更换、环境全面清洁\", \"服务时间: 每日9:00-18:00\", \"专为多猫家庭设计\", \"适合养有多只猫咪的家庭\", \"服务完成后提供清洁报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'regular', '89.00', 60, 'https://situationship.icu/upload/files/files-20260324004505-55dedad8.jpg', '#e1f5fe', '[\"上门服务\", \"多猫家庭\", \"批量服务\"]', 'active', 0, 6, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0),
(36, '周末铲屎服务', '周末专属铲屎服务，让您在周末也能享受专业的铲屎服务。包括清理、更换猫砂、环境整理，让您和爱宠度过愉快的周末。', '[\"适用宠物: 猫咪、狗狗\", \"适用宠物性别: 公母均可\", \"服务范围: 室内宠物生活区域清洁\", \"服务时长: 30分钟\", \"包含内容: 清理、更换猫砂、环境整理\", \"服务时间: 周末9:00-18:00\", \"周末专属服务\", \"让您和爱宠度过愉快的周末\", \"服务完成后提供清洁报告\"]', '[\"购买后凭电子券码预约使用\", \"需提前2小时电话预约\", \"节假日价格可能浮动，详情请咨询客服\"]', 'basic', '45.00', 30, 'https://situationship.icu/upload/files/files-20260324004539-b6da9500.jpg', '#f1f8e9', '[\"上门服务\", \"周末服务\"]', 'active', 0, 7, '2025-11-06 16:00:03', '2025-11-06 16:00:03', 0);

