CREATE TABLE `notice` (
  `id` bigint NOT NULL COMMENT '公告ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告内容',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '公告类型（system、marketing、update等）',
  `status` int DEFAULT '0' COMMENT '状态：0-草稿，1-已发布，2-已下线',
  `is_top` int DEFAULT '0' COMMENT '是否置顶：0-否，1-是',
  `effective_time` datetime DEFAULT NULL COMMENT '生效时间（为空则立即生效）',
  `expire_time` datetime DEFAULT NULL COMMENT '失效时间（为空则长期有效）',
  `sort_order` int DEFAULT '0' COMMENT '排序值（越大越靠前）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告表' ROW_FORMAT=DYNAMIC;

