--
-- 表的结构 `post`
--

CREATE TABLE `post` (
  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '标签列表，用逗号分隔',
  `images` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `videos` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '视频列表(JSON格式，包含视频URL和封面)',
  `likes_count` int DEFAULT '0',
  `comments_count` int DEFAULT '0',
  `status` int DEFAULT '1',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_top` tinyint(1) DEFAULT '0' COMMENT '是否置顶',
  `is_hot` tinyint(1) DEFAULT '0' COMMENT '是否热门',
  `exposure_score` double DEFAULT '0' COMMENT '曝光分数，用于热度算法',
  `views_count` int DEFAULT '0' COMMENT '浏览数',
  `shares_count` int DEFAULT '0' COMMENT '分享数',
  `image_count` int DEFAULT '0' COMMENT '图片数量',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '封面图片'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='帖子表' ROW_FORMAT=DYNAMIC;

