--
-- 表的结构 `recommendation_interaction_weight`
--

CREATE TABLE `recommendation_interaction_weight` (
  `id` bigint NOT NULL COMMENT '主键',
  `interaction_type` varchar(20) NOT NULL COMMENT '行为类型: like/comment/collect/view',
