--
-- 表的结构 `service_config`
--

CREATE TABLE `service_config` (
  `id` bigint NOT NULL COMMENT '服务配置ID',
  `service_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型标识（如：door-cleaning, grooming等）',
  `service_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '服务描述',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '服务价格',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务图标路径',
  `image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务图片路径',
  `time_slots` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '可预约时间段（JSON格式）',
  `service_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务区域',
  `max_bookings_per_day` int DEFAULT '10' COMMENT '每日最大预约数',
  `status` int DEFAULT '1' COMMENT '状态（1-启用，0-禁用）',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `features` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '服务特点（JSON格式）',
  `notice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '温馨提示（JSON格式）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务配置表' ROW_FORMAT=DYNAMIC;

