--
-- 表的结构 `service_member`
--

CREATE TABLE `service_member` (
  `id` bigint NOT NULL COMMENT '服务人员ID',
  `user_id` bigint DEFAULT NULL COMMENT '关联用户ID（可为空，表示服务人员尚未注册系统账户）',
  `service_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型（如：door-cleaning, grooming等）',
  `store_id` bigint DEFAULT NULL COMMENT '所属门店ID，NULL表示平台级可参与任意门店',
  `member_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务人员姓名',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像URL',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `status` int DEFAULT '1' COMMENT '状态：1-启用，0-禁用',
  `max_tasks_per_day` int DEFAULT '10' COMMENT '每日最大任务数',
  `rating` decimal(3,2) DEFAULT '5.00' COMMENT '评分（0-5分）',
  `total_tasks` int DEFAULT '0' COMMENT '累计完成任务数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务人员表' ROW_FORMAT=DYNAMIC;

