--
-- 表的结构 `service_schedule`
--

CREATE TABLE `service_schedule` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `member_id` bigint NOT NULL COMMENT '服务人员ID',
  `store_id` bigint DEFAULT NULL COMMENT '所属门店ID，排班所属门店（与 member 的 store_id 独立）',
  `service_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'door-cleaning',
  `date` date NOT NULL COMMENT '日期，例如 2025-11-03',
  `time_slot` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '时间段，例如 "09:00-10:00"',
  `max_capacity` int DEFAULT '1',
  `reserved_count` int DEFAULT '0',
  `is_available` tinyint DEFAULT '1',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '可预约' COMMENT '状态：可预约、已预约',
  `task_id` bigint DEFAULT NULL COMMENT '若被占用，关联appointment.id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='服务人员可预约时间表' ROW_FORMAT=DYNAMIC;

