--
-- 表的结构 `task_records`
--

CREATE TABLE `task_records` (
  `id` bigint NOT NULL COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `task_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务类型（daily_signin, share_app等）',
  `task_date` date NOT NULL COMMENT '任务日期',
  `progress` int NOT NULL DEFAULT '0' COMMENT '任务进度',
  `target` int NOT NULL DEFAULT '1' COMMENT '目标值',
  `completed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已完成（0-未完成，1-已完成）',
  `claimed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已领取奖励（0-未领取，1-已领取）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='任务记录表' ROW_FORMAT=DYNAMIC;

